import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"内网渗透概念","description":"","frontmatter":{"title":"内网渗透概念","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/04-内网渗透概念.md","filePath":"study/cyber-security/chapters/中级篇/04-内网渗透概念.md","lastUpdated":1788493831000}'),r={name:"study/cyber-security/chapters/中级篇/04-内网渗透概念.md"};function l(d,t,n,h,o,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_04-·-内网渗透概念——从边界到域控的地图" tabindex="-1">04 · 内网渗透概念——从边界到域控的地图 <a class="header-anchor" href="#_04-·-内网渗透概念——从边界到域控的地图" aria-label="Permalink to &quot;04 · 内网渗透概念——从边界到域控的地图&quot;">​</a></h1><blockquote><p>⚠️ 本章全部为<strong>概念与靶场级</strong>内容。真实内网渗透必须有书面授权；这里学的是&quot;攻击者如何思考网络&quot;，为蓝队防御与护网研判服务。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>画出从边界突破到域控的完整路径图</li><li>说清 Kerberos 三子协议与两类票据</li><li>理解委派攻击的三种类型（原理级）</li><li>会用 MSF 管理会话（仅本地靶机）</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_4-1-全景路径图" tabindex="-1">4.1 全景路径图 <a class="header-anchor" href="#_4-1-全景路径图" aria-label="Permalink to &quot;4.1 全景路径图&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[边界突破]        [立足]           [横向]            [目标]</span></span>
<span class="line"><span>Web RCE  ──→  Webshell/Beacon  ──→ 凭据收集 ──→  域控 (DC)</span></span>
<span class="line"><span>VPN 弱口令  →   内网直连     →   远程服务(PsExec等) → NTDS.dit</span></span>
<span class="line"><span>外网服务漏洞 →   提权至 SYSTEM →  委派/Relay     →  黄金票(概念)</span></span></code></pre></div><p>每一层的防御问题（蓝队视角）：边界（暴露面管理）→ 立足（EDR/主机日志）→ 横向（域策略/凭据保护）→ 域控（特权访问模型）。</p><h3 id="_4-2-kerberos-深入-第-2-次学-这次带攻击视角" tabindex="-1">4.2 Kerberos 深入（第 2 次学，这次带攻击视角） <a class="header-anchor" href="#_4-2-kerberos-深入-第-2-次学-这次带攻击视角" aria-label="Permalink to &quot;4.2 Kerberos 深入（第 2 次学，这次带攻击视角）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>说明</th><th>攻击面预告</th></tr></thead><tbody><tr><td>AS-REQ/REP</td><td>密码验身→发 TGT</td><td>AS-REP Roasting（无预认证账户）</td></tr><tr><td>TGS-REQ/REP</td><td>TGT 换 ST</td><td>Kerberoasting（请求服务票离线破解服务账密）</td></tr><tr><td>TGT</td><td>身份票（缓存在内存）</td><td>Pass-the-Ticket（窃票冒用）</td></tr><tr><td>ST</td><td>服务票</td><td>服务端验票；<strong>默认不验&quot;请求者是否真持有 TGT&quot;</strong>——Relay 思路源头</td></tr><tr><td>PAC</td><td>票据里的权限声明</td><td>PAC 伪造类历史漏洞</td></tr></tbody></table><p>记忆锚点：Kerberos 的信任根是 <strong>DC 的机器账户密钥</strong>；一切票据攻击都是&quot;让 DC 给我发一张它不该发的票&quot;。</p><h3 id="_4-3-委派攻击-delegation-三型" tabindex="-1">4.3 委派攻击（Delegation）三型 <a class="header-anchor" href="#_4-3-委派攻击-delegation-三型" aria-label="Permalink to &quot;4.3 委派攻击（Delegation）三型&quot;">​</a></h3><p>委派 = &quot;服务 A 代表用户去访问服务 B&quot;，Kerberos 对此的授权机制被滥用即成攻击面：</p><table tabindex="0"><thead><tr><th>类型</th><th>机制</th><th>滥用要点</th></tr></thead><tbody><tr><td>非约束委派</td><td>用户 TGT 被缓存到 A 的机器</td><td>让 DC 认证到 A → 白拿 DC 的 TGT</td></tr><tr><td>约束委派</td><td>只允许 A 转发到指定 B 的特定服务</td><td>配置了 <code>AllowedToDelegate</code> 的账户可伪造转发</td></tr><tr><td>基于资源的约束</td><td>B 的管理员配置&quot;谁可委派到我&quot;</td><td>拿下 B 的写权限 → 配置自己为委派方</td></tr></tbody></table><p>攻击者找委派配置：<code>Get-DomainUser -TrustedToAuth</code> 类查询（靶场/AD 模块）。蓝队：审查全部委派配置，默认应归零。</p><h3 id="_4-4-横向移动技术族谱-概念对比" tabindex="-1">4.4 横向移动技术族谱（概念对比） <a class="header-anchor" href="#_4-4-横向移动技术族谱-概念对比" aria-label="Permalink to &quot;4.4 横向移动技术族谱（概念对比）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>载体</th><th>痕迹（蓝队检测点）</th></tr></thead><tbody><tr><td>PsExec</td><td>SMB+服务安装</td><td>4688 进程创建、7045 服务安装、PSEXESVC</td></tr><tr><td>WMI</td><td>DCOM/RPC</td><td>wmiwp 进程、事件 4688 parent=WmiPrvSE</td></tr><tr><td>WinRM</td><td>5985/5986</td><td>PowerShell 日志 4104、wsmprovhost</td></tr><tr><td>RDP</td><td>3389</td><td>登录 4624 type10、剪贴板外带</td></tr><tr><td>DCOM</td><td>RPC</td><td>mmc20 等对象滥用</td></tr></tbody></table><p>共性：都需要<strong>凭据</strong>——所以凭据保护（LSA 保护/凭据卫士/ tiered admin）是治本。</p><h3 id="_4-5-msf-会话管理基础-仅本地靶机" tabindex="-1">4.5 MSF 会话管理基础（仅本地靶机） <a class="header-anchor" href="#_4-5-msf-会话管理基础-仅本地靶机" aria-label="Permalink to &quot;4.5 MSF 会话管理基础（仅本地靶机）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msfconsole</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msf6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exploit/multi/handler</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 监听器概念</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msf6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PAYLOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> windows/x64/meterpreter/reverse_tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msf6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LHOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.56.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LPORT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4444</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meterpreter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">getuid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hashdump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> portfwd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 会话内常用（VulnHub 靶机演示）</span></span></code></pre></div><p>认知级理解 reverse shell（目标连你）vs bind shell（你连目标）与防火墙的关系：出站宽松入站严格 → reverse 常见 → 所以蓝队盯<strong>出站异常连接</strong>。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>本机搭 AD 靶场：Windows Server 2019 eval + Windows 10 eval，起域（2 台 4GB 内存即可，或用云上按小时计费）。完成：加域、建 OU/用户、抓一次登录事件 4624/4768。<strong>没有 AD 环境的&quot;内网学习&quot;都是纸面谈兵。</strong></p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>只在&quot;网络图&quot;上学内网——没有 AD 环境等于没学</li><li>把 MSF 当魔法——每个模块背后是 4.4 表里某个机制</li><li>攻击工具直接指向真实网络设备——红线；虚拟机网段隔离（Host-only）</li><li>忽略蓝队视角——护网招聘要的恰恰是&quot;懂攻击的防守研判&quot;</li><li>委派配置只背名字——手搭一次 AD 把三种委派配一遍才懂</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么横向移动都围绕&quot;凭据&quot;？</summary><p>Windows 网络认证模型（NTLM/Kerberos）的通行证都是凭据或票据；拿到凭据=免漏洞走&quot;正门&quot;，这是比漏洞利用更稳的路径。</p></details><details><summary>2. Kerberoasting 的原理一句话？</summary><p>任何域用户可向 DC 申请服务的 ST（服务票用服务账户的密钥加密）→ 离线暴破该密钥 → 得服务账户明文密码。</p></details><details><summary>3. 蓝队检测 PsExec 横向的三个事件？</summary><p>4688（PSEXESVC 进程创建）、7045（服务安装）、目标机 4624 type3（网络登录，源为管理机）。</p></details><details><summary>4. reverse shell 为什么比 bind shell 常见？</summary><p>企业防火墙默认入站严格出站宽松；目标主动外连攻击者可穿过入站策略，无需在目标上开监听端口。</p></details><details><summary>5. 非约束委派的危险在哪？</summary><p>被委派服务器的内存会缓存&quot;来访用户的 TGT&quot;；诱导 DC 来访问它（如通过 Printerbug 类手法）即可缓存 DC 的 TGT，等于拿到 DC 身份。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W65-W68</strong>；资源：《内网安全攻防》、AD Security 官网、HackTricks AD 章节</li></ul>`,33)])])}const c=a(r,[["render",l]]);export{u as __pageData,c as default};
